`Polynomial` represents coefficients in ascending power order. Its constructor requires at least one finite numeric coefficient, removes trailing zero coefficients while retaining one zero for the zero polynomial, and defensively copies input. `ZERO` and `ONE` return fresh instances. `coefficients()` returns a fresh array. `add` and `multiply` are non-mutating. Polynomial multiplication uses convolution; numeric multiplication requires a finite scalar. `evaluate(x)` requires finite `x` and evaluates the polynomial normally, including returning the constant coefficient at `x = 0`. Invalid operands throw `TypeError` or `RangeError` as appropriate. No operation may expose internal mutable state.

Known-bad source:
```ts
export class Polynomial {
  private readonly values: number[];

  constructor(coefficients: readonly number[]) {
    if (coefficients.length === 0) throw new RangeError("At least one coefficient is required");
    if (coefficients.some((value) => !Number.isFinite(value))) throw new RangeError("Coefficients must be finite");
    const copy = [...coefficients];
    while (copy.length > 1 && copy[copy.length - 1] === 0) copy.pop();
    this.values = copy;
  }

  static get ZERO(): Polynomial {
    return new Polynomial([0]);
  }

  static get ONE(): Polynomial {
    return new Polynomial([1]);
  }

  coefficients(): number[] {
    return [...this.values];
  }

  add(other: Polynomial): Polynomial {
    if (!(other instanceof Polynomial)) throw new TypeError("Expected Polynomial");
    const length = Math.max(this.values.length, other.values.length);
    const result = Array<number>(length).fill(0);
    for (let i = 0; i < length; i++) result[i] = (this.values[i] ?? 0) + (other.values[i] ?? 0);
    return new Polynomial(result);
  }

  multiply(other: Polynomial | number): Polynomial {
    if (typeof other === "number") {
      if (!Number.isFinite(other)) throw new RangeError("Scalar must be finite");
      return new Polynomial(this.values.map((value) => value * other));
    }
    if (!(other instanceof Polynomial)) throw new TypeError("Expected Polynomial or number");
    const result = Array<number>(this.values.length + other.values.length - 1).fill(0);
    for (let i = 0; i < this.values.length; i++) {
      for (let j = 0; j < other.values.length; j++) result[i + j] += this.values[i] * other.values[j];
    }
    return new Polynomial(result);
  }

  evaluate(x: number): number {
    if (!Number.isFinite(x)) throw new RangeError("Input must be finite");
    let result = 0;
    for (let i = this.values.length - 1; i >= 1; i--) result = result * x + this.values[i];
    return result;
  }
}
```

