import { Polynomial } from "./solution";

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function arrayEqual(actual: readonly number[], expected: readonly number[], message: string): void {
  if (actual.length !== expected.length || actual.some((value, index) => !Object.is(value, expected[index]))) {
    throw new Error(`${message}: expected [${expected}], got [${actual}]`);
  }
}
function expectError(action: () => void, constructor: typeof Error): void {
  let thrown: unknown;
  try { action(); } catch (error) { thrown = error; }
  assert(thrown instanceof constructor, `expected ${constructor.name}`);
}

expectError(() => new Polynomial([]), RangeError);
expectError(() => new Polynomial([1, Infinity]), RangeError);
expectError(() => new Polynomial([NaN]), RangeError);

const source = [1, 2, 0, 0];
const polynomial = new Polynomial(source);
source[0] = 99;
arrayEqual(polynomial.coefficients(), [1, 2], "constructor copy/trailing zeros");
const exposed = polynomial.coefficients();
exposed[0] = 50;
arrayEqual(polynomial.coefficients(), [1, 2], "coefficients must return a copy");
arrayEqual(new Polynomial([0, 0, 0]).coefficients(), [0], "zero polynomial normalization");

const zeroA = Polynomial.ZERO;
const zeroB = Polynomial.ZERO;
const oneA = Polynomial.ONE;
const oneB = Polynomial.ONE;
assert(zeroA !== zeroB, "ZERO must return fresh instances");
assert(oneA !== oneB, "ONE must return fresh instances");
arrayEqual(zeroA.coefficients(), [0], "ZERO coefficients");
arrayEqual(oneA.coefficients(), [1], "ONE coefficients");

const left = new Polynomial([1, 2, 3]);
const right = new Polynomial([4, 5]);
arrayEqual(left.add(right).coefficients(), [5, 7, 3], "addition");
arrayEqual(left.multiply(right).coefficients(), [4, 13, 22, 15], "convolution multiplication");
arrayEqual(left.multiply(2).coefficients(), [2, 4, 6], "scalar multiplication");
arrayEqual(left.multiply(0).coefficients(), [0], "zero scalar normalization");
arrayEqual(left.coefficients(), [1, 2, 3], "operations must not mutate left operand");
arrayEqual(right.coefficients(), [4, 5], "operations must not mutate right operand");

if (left.evaluate(0) !== 1) throw new Error("evaluation at zero must return constant coefficient");
if (left.evaluate(2) !== 17) throw new Error("normal evaluation incorrect");
if (new Polynomial([-3]).evaluate(10) !== -3) throw new Error("constant evaluation incorrect");
expectError(() => left.evaluate(Infinity), RangeError);
expectError(() => left.multiply(NaN), RangeError);
expectError(() => left.add(3 as unknown as Polynomial), TypeError);
expectError(() => left.multiply("2" as unknown as Polynomial), TypeError);

